var e={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Zautomatyzuj swoją drukarkę bezpiecznymi regułami JEŻELI-TO. Domyślnie wyłączone; uzbrój każdą regułę samodzielnie.`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Nie ma jeszcze żadnych reguł. Dodaj jedną poniżej, a następnie uzbrój ją, gdy będziesz gotowy.`}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:`Silnik reguł jest WŁĄCZONY`}},off:{t:0,b:{t:2,i:[{t:3}],s:`Silnik reguł jest WYŁĄCZONY`}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:`Włącz`}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:`Wyłącz`}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:`Nic nie zadziała, dopóki nie będą włączone jednocześnie silnik i dana reguła.`}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:`Gdy druk się zakończy`}},print_error:{t:0,b:{t:2,i:[{t:3}],s:`Gdy w drukarce wystąpi błąd`}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:`Gdy grzałka przekroczy`}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:`Gdy grzałka spadnie poniżej`}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:`Zarejestruj powiadomienie`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`Wykonaj polecenie g-code`}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:`Uzbrojona`}},arm:{t:0,b:{t:2,i:[{t:3}],s:`Rozbrojona`}},edit:{t:0,b:{t:2,i:[{t:3}],s:`Edytuj`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Usuń`}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:`Usuń regułę`}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:`Nazwa reguły`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`np. Wyłącz grzałki po druku`}},trigger:{t:0,b:{t:2,i:[{t:3}],s:`Jeżeli (wyzwalacz)`}},action:{t:0,b:{t:2,i:[{t:3}],s:`To (akcja)`}},heater:{t:0,b:{t:2,i:[{t:3}],s:`Grzałka`}},value:{t:0,b:{t:2,i:[{t:3}],s:`Temperatura (°C)`}},message:{t:0,b:{t:2,i:[{t:3}],s:`Komunikat`}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Wyświetlany w dzienniku reguł`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`np. TURN_OFF_HEATERS`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Zapisz regułę`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Anuluj`}},add:{t:0,b:{t:2,i:[{t:3}],s:`Dodaj regułę`}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:`Ostatnia aktywność`}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:`powiadomiono`}},ran:{t:0,b:{t:2,i:[{t:3}],s:`wykonano g-code`}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:`pominięto (drukarka zajęta)`}},error:{t:0,b:{t:2,i:[{t:3}],s:`błąd`}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Przewodnik`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Przewodnik po silniku reguł`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Zamknij`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Czym jest silnik reguł?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Obserwuje drukarkę i wykonuje akcję, gdy spełniony zostanie ustawiony przez Ciebie warunek - na przykład zarejestruj notatkę po zakończeniu druku albo wyłącz grzałki. Każda reguła to JEŻELI (wyzwalacz) TO (akcja).`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`Jak zachowuje bezpieczeństwo`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Silnik jest domyślnie wyłączony, a każdą regułę trzeba uzbroić osobno, więc nic nie zadziała niespodziewanie. Reguła wyzwala się raz, gdy jej warunek po raz pierwszy stanie się prawdziwy. Akcje g-code działają tylko wtedy, gdy drukarka jest bezczynna - podczas druku są odrzucane - a każdy wynik jest rejestrowany.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Słowniczek`}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:`Wyzwalacz`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Warunek, który uruchamia regułę, np. zakończenie druku lub przekroczenie temperatury przez grzałkę.`}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:`Akcja`}},def:{t:0,b:{t:2,i:[{t:3}],s:`To, co reguła robi po wyzwoleniu: rejestruje powiadomienie albo wykonuje polecenie g-code (tylko gdy drukarka jest bezczynna).`}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:`Uzbrojona`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Reguła, która jest włączona. Rozbrojone reguły są zachowywane, ale nigdy się nie wyzwalają.`}}}}}}};export{e as default};